}

#include <Arduino.h>
#include <Wire.h>
#include <RTClib.h>
#include <TM1637Display.h>

RTC_DS3231 rtc;
TM1637Display disp(PB12, PB13);   // CLK, DIO
const int BTN_SET = PB14, BTN_ADD = PB15, BUZZ = PA1;
int alarmH = 7, alarmM = 0;
bool alarmOn = true;

void setup() {
  Serial.begin(115200);
  Wire.begin();
  rtc.begin();
  if (rtc.lostPower()) rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  disp.setBrightness(4);          // 0-7
  pinMode(BTN_SET, INPUT_PULLUP); pinMode(BTN_ADD, INPUT_PULLUP);
}

void loop() {
  DateTime now = rtc.now();
  bool colon = now.second() % 2 == 0;
  disp.showNumberDecEx(now.hour() * 100 + now.minute(), colon ? 0b01000000 : 0, true);

  disp.setBrightness(now.hour() >= 22 || now.hour() < 7 ? 1 : 5);   // Dim at night

  if (digitalRead(BTN_ADD) == LOW) {        // Add one minute (simple time setting)
    rtc.adjust(now + TimeSpan(60));
    delay(200);
  }
  if (alarmOn && now.hour() == alarmH && now.minute() == alarmM && now.second() < 30) {
    tone(BUZZ, 2000); delay(200); noTone(BUZZ); delay(200);
    if (digitalRead(BTN_SET) == LOW) alarmOn = false;   // Any key silences the alarm
  }
  delay(100);
}

#include <Arduino.h>
#include <SPI.h>
#include <MFRC522.h>
#include <Servo.h>

MFRC522 rfid(PA4, PB0);            // SS, RST; SPI1 defaults to PA5/PA6/PA7
Servo lock;
const int SERVO = PA8, BUZZ = PA1, GREEN = PA2, RED = PA3;
// Run it once to print the UID, then put your card here
const byte ALLOWED[][4] = { {0xA3, 0x5F, 0x12, 0x9C}, {0x10, 0x22, 0x33, 0x44} };
int badCount = 0;

bool isAllowed(byte* uid) {
  for (auto &card : ALLOWED) if (memcmp(card, uid, 4) == 0) return true;
  return false;
}

void setup() {
  Serial.begin(115200);
  SPI.begin();
  rfid.PCD_Init();
  lock.attach(SERVO); lock.write(0);
  pinMode(BUZZ, OUTPUT); pinMode(GREEN, OUTPUT); pinMode(RED, OUTPUT);
  Serial.println("Please tap your card");
}

void loop() {
  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) return;
  Serial.print("UID: ");
  for (byte i = 0; i < rfid.uid.size; i++) { Serial.print(rfid.uid.uidByte[i], HEX); Serial.print(' '); }
  Serial.println();

  if (isAllowed(rfid.uid.uidByte)) {
    badCount = 0;
    digitalWrite(GREEN, HIGH); tone(BUZZ, 2000, 100); delay(150); tone(BUZZ, 2500, 100);
    lock.write(90); delay(3000); lock.write(0);
    digitalWrite(GREEN, LOW);
  } else {
    digitalWrite(RED, HIGH); tone(BUZZ, 300, 600); delay(700); digitalWrite(RED, LOW);
    if (++badCount >= 3) { for (int i = 0; i < 20; i++) { tone(BUZZ, 800, 200); digitalWrite(RED, i % 2); delay(500); } badCount = 0; }
  }
  rfid.PICC_HaltA();              // Put this card to "sleep", otherwise it keeps getting read
  rfid.PCD_StopCrypto1();
}

#include <Arduino.h>
#include <TinyGPSPlus.h>
#include <SPI.h>
#include <SdFat.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

HardwareSerial GPS(PA3, PA2);         // RX, TX -> USART2
TinyGPSPlus gps;
SdFat sd;
SdFile logFile;
Adafruit_SSD1306 oled(128, 64, &Wire, -1);
const int SD_CS = PB12, BTN = PB13;
bool recording = false;
unsigned long lastLog = 0;
int lastBtn = HIGH;

void setup() {
  Serial.begin(115200);
  GPS.begin(9600);                    // NEO-6M default is 9600
  Wire.begin();
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C); oled.setTextColor(WHITE);
  pinMode(BTN, INPUT_PULLUP);
  if (!sd.begin(SD_CS, SD_SCK_MHZ(4))) Serial.println("SD card init failed");
}

void loop() {
  while (GPS.available()) gps.encode(GPS.read());   // Feed characters to the parser

  int b = digitalRead(BTN);
  if (b == LOW && lastBtn == HIGH) {
    recording = !recording;
    if (recording) { logFile.open("track.csv", O_WRONLY | O_CREAT | O_APPEND); logFile.println("time,lat,lng,kmh"); }
    else logFile.close();
    delay(50);
  }
  lastBtn = b;

  if (millis() - lastLog >= 1000) {
    lastLog = millis();
    oled.clearDisplay(); oled.setTextSize(1); oled.setCursor(0, 0);
    oled.print("sats "); oled.print(gps.satellites.value()); oled.println(recording ? "  REC" : "");
    if (gps.location.isValid()) {
      oled.print(gps.location.lat(), 5); oled.println();
      oled.print(gps.location.lng(), 5); oled.println();
      oled.setTextSize(2); oled.print(gps.speed.kmph(), 1); oled.print(" km/h");
      if (recording && logFile.isOpen()) {
        logFile.print(gps.time.value()); logFile.print(',');
        logFile.print(gps.location.lat(), 6); logFile.print(',');
        logFile.print(gps.location.lng(), 6); logFile.print(',');
        logFile.println(gps.speed.kmph(), 1);
        logFile.sync();                                   // Flush to the card every second so a power loss doesn't lose data
      }
    } else {
      oled.println("searching...");
    }
    oled.display();
  }
}
